PRAGMA foreign_keys = ON;

CREATE TABLE students (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  first_name TEXT NOT NULL,
  last_name TEXT NOT NULL,
  national_code TEXT UNIQUE,
  birth_date DATE,
  email TEXT UNIQUE,
  enrolled_at DATE NOT NULL DEFAULT (date('now'))
);

CREATE TABLE teachers (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  full_name TEXT NOT NULL,
  email TEXT UNIQUE,
  hire_date DATE,
  department TEXT
);

CREATE TABLE classes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  grade INTEGER,
  teacher_id INTEGER NOT NULL REFERENCES teachers (id) ON DELETE RESTRICT ON UPDATE CASCADE,
  room TEXT,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE enrollments (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  student_id INTEGER NOT NULL REFERENCES students (id) ON DELETE CASCADE ON UPDATE CASCADE,
  class_id INTEGER NOT NULL REFERENCES classes (id) ON DELETE CASCADE ON UPDATE CASCADE,
  enrolled_at DATE NOT NULL DEFAULT (date('now')),
  UNIQUE (student_id, class_id)
);

CREATE TABLE grades (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  enrollment_id INTEGER NOT NULL REFERENCES enrollments (id) ON DELETE CASCADE ON UPDATE CASCADE,
  subject TEXT NOT NULL,
  score REAL NOT NULL CHECK (score >= 0 AND score <= 20),
  term TEXT NOT NULL DEFAULT 'term-1',
  recorded_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_classes_teacher ON classes (teacher_id);
CREATE INDEX idx_enrollments_student ON enrollments (student_id);
CREATE INDEX idx_enrollments_class ON enrollments (class_id);
CREATE INDEX idx_grades_enrollment ON grades (enrollment_id);
